export function Panel({
  title = "{{title}}",
  body = "{{body}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
  padding = {{padding}},
}) {
  const wrap = {
    bordered: { border: `1.5px solid ${accent}` },
    raised: { border: "1px solid transparent", boxShadow: "0 6px 18px rgba(36,20,48,.14)" },
    tinted: { border: "1px solid transparent", background: `color-mix(in srgb, ${accent} 22%, #FAF7F2)` },
  }[variant] ?? {};
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2", boxSizing: "border-box", borderRadius: 8, maxWidth: 340, padding, ...wrap }}>
      <h4 style={{ margin: "0 0 8px", fontSize: 15, fontWeight: 600 }}>{title}</h4>
      <p style={{ margin: 0, color: "#241430cc" }}>{body}</p>
    </div>
  );
}
